#include <juce_audio_utils/juce_audio_utils.h>
#include <iostream>
#include <stdexcept>
int main(int argc,char**argv){juce::ScopedJuceInitialiser_GUI gui;try{juce::VST3PluginFormat fmt;juce::OwnedArray<juce::PluginDescription>types;fmt.findAllTypesForFile(types,argv[1]);if(types.size()!=1)throw std::runtime_error("identity");juce::File dir(argv[2]);for(int rate:{44100,48000})for(float ratio:{1.f,20.f}){juce::String error;auto p=fmt.createInstanceFromDescription(*types[0],rate,257,error);if(!p)throw std::runtime_error("load");for(auto*a:p->getParameters())if(a->getName(100)=="Ratio")a->setValueNotifyingHost((ratio-1)/19);p->prepareToPlay(rate,257);juce::MidiBuffer midi;juce::AudioBuffer<float>warm(2,257);for(int k=0;k<20;k++){warm.clear();p->processBlock(warm,midi);}p->releaseResources();p->prepareToPlay(rate,257);juce::MemoryBlock bytes;dir.getChildFile("dry-"+juce::String(rate)+".f32").loadFileAsData(bytes);auto*x=(float*)bytes.getData();int n=int(bytes.getSize()/8);std::vector<float>out(n*2);double err=0;for(int pos=0;pos<n;pos+=257){int count=std::min(257,n-pos);juce::AudioBuffer<float>b(2,count);for(int c=0;c<2;c++)for(int i=0;i<count;i++)b.setSample(c,i,x[2*(pos+i)+c]);p->processBlock(b,midi);for(int c=0;c<2;c++)for(int i=0;i<count;i++){float y=b.getSample(c,i);if(!std::isfinite(y))throw std::runtime_error("nonfinite");out[2*(pos+i)+c]=y;err=std::max(err,double(fabs(y-x[2*(pos+i)+c])));}}if(ratio==1&&err!=0)throw std::runtime_error("unity");dir.getChildFile("updated-"+juce::String(rate)+"-"+juce::String(int(ratio))+".f32").replaceWithData(out.data(),out.size()*4);std::cout<<"PASS actual VST3 "<<rate<<" Hz ratio "<<ratio<<" finite output"<<(ratio==1?", exact unity":"")<<std::endl;}return 0;}catch(const std::exception&e){std::cerr<<e.what();return 1;}}
